    ["%", ["Discount 50% off"]],
    ["_", ["snake_case rename"]],
    ['"x"', ["Read (chapter 3)"]],
    ["\\", ["Read (chapter 3)"]],
  ])("treats special characters in %j literally", async (q, expected) => {
    expect(await titles({ q })).toEqual(expected);
  });

