    expect(await titles({ status: "done", priority: "1" })).toEqual([]);
  });

  it("ignores invalid filter values", () => {
    expect(parseFilters({ status: "nope", priority: "9", q: "  x " })).toEqual({
      q: "x",
      status: null,
      priority: null,
    });
  });
});
