async () => {
  const wait = ms => new Promise(r => setTimeout(r, ms));
  // capture download
  let csv = null; const origCreate = URL.createObjectURL;
  URL.createObjectURL = (b) => { b.text().then(t => csv = t); return 'blob:x'; };
  const origClick = HTMLAnchorElement.prototype.click; let dlName;
  HTMLAnchorElement.prototype.click = function() { dlName = this.download; };
  [...document.querySelectorAll('button')].find(b => b.textContent.startsWith('Download')).click();
  await wait(300);
  URL.createObjectURL = origCreate; HTMLAnchorElement.prototype.click = origClick;
  const out = { dlName, csvHead: csv?.slice(0, 400) };
  const input = document.querySelector('input[type=file]');
  const tryFile = async (name, content, type) => {
    const dt = new DataTransfer(); dt.items.add(new File([content], name, { type })); input.files = dt.files;
    [...document.querySelectorAll('button')].find(b => b.textContent === 'Import').click();
    await wait(2000);
    return document.querySelector('.banner')?.innerText ?? document.querySelector('.summary')?.innerText;
  };
  out.empty = await tryFile('e.csv', '', 'text/csv');
  out.png = await tryFile('x.png', 'abc', 'image/png');
  out.missingCol = await tryFile('m.csv', 'title,due_date\nA,2026-01-01', 'text/csv');
  out.big = await tryFile('b.csv', 'a'.repeat(1024*1024+10), 'text/csv');
  out.latin1 = await tryFile('l.csv', new Uint8Array([0x74,0x69,0x74,0x6c,0x65,0x0a,0xe9,0xff]), 'text/csv');
  return out;
}

