  const wait = ms => new Promise(r => setTimeout(r, ms));
  const items = () => [...document.querySelectorAll('li.task')];
  const find = t => items().find(li => li.querySelector('.task-title')?.innerText === t);
  const set = (el, v) => { const proto = el instanceof HTMLSelectElement ? HTMLSelectElement : el instanceof HTMLTextAreaElement ? HTMLTextAreaElement : HTMLInputElement; Object.getOwnPropertyDescriptor(proto.prototype, 'value').set.call(el, v); el.dispatchEvent(new Event('input', {bubbles: true})); el.dispatchEvent(new Event('change', {bubbles: true})); };
  const out = { initial: items().map(li => li.querySelector('.task-title').innerText) };
  // toggle complete
  find('Call the plumber').querySelector('input[type=checkbox]').click(); await wait(2000);
  out.afterToggle = find('Call the plumber').className;
  // edit
  [...find('Team lunch').querySelectorAll('button')].find(b => b.textContent === 'Edit').click(); await wait(300);
  let f = document.querySelector('li.task.editing form');
