  f.querySelector('button[type=submit]').click(); await wait(2000);
  f = document.querySelector('li.task.editing form');
  out.editError = f?.querySelector('[role=alert]')?.innerText;
  set(f.querySelector('[name=title]'), 'Team lunch (Friday)');
  f.querySelector('button[type=submit]').click(); await wait(2000);
  out.afterEdit = find('Team lunch (Friday)')?.innerText.replace(/\n/g,' | ');
  // delete w/ confirm
  [...find('Write "Q4" report').querySelectorAll('button')].find(b => b.textContent === 'Delete').click(); await wait(200);
  out.confirm = find('Write "Q4" report').querySelector('.task-actions').innerText.replace(/\n/g,' ');
  [...find('Write "Q4" report').querySelectorAll('button')].find(b => b.textContent === 'Delete').click(); await wait(2000);
  out.afterDelete = items().map(li => li.querySelector('.task-title')?.innerText);
  return out;
}

